{"l":7664,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'bevidst' på engelsk?","o":["cautious","anxious","precious","conscious"],"a":"conscious","r":"'Conscious' betyder bevidst. Samvittighed hedder 'conscience'."},
{"l":7673,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'opnå / skaffe' på engelsk i 'You must ___ permission'?","o":["obtain","contain","retain","observe"],"a":"obtain","r":"'Obtain' = få, skaffe."},
{"l":7683,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'søgemaskine' på engelsk?","o":["fire engine","search engine","search party","screen saver"],"a":"search engine","r":"'Search engine' = søgemaskine."},
{"l":7690,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man uformelt vil spørge, om en ven har lyst til at være med?","o":["Do you like to join us?","Are you fancy joining us?","Do you fancy joining us?","Do you want that we join?"],"a":"Do you fancy joining us?","r":"'Do you fancy + -ing' er en uformel måde at spørge, om nogen har lyst. 'Do you like to' betyder kan du lide at."},
