{"l":9090,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'curb' i 'The town wants to curb traffic near the school.'?","o":["overvåge","omdirigere","begrænse","fremme"],"a":"begrænse","r":"'Curb' betyder at begrænse eller holde noget i tømme."},
{"l":9101,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'nøje undersøgelse' på engelsk?","o":["mutiny","scarcity","security","scrutiny"],"a":"scrutiny","r":"'Scrutiny' betyder grundig gennemgang eller kritisk undersøgelse."},
{"l":9110,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'All I wanted ___ a quiet evening with a good book.'","o":["was","were","has","did"],"a":"was","r":"'All I wanted' fungerer som ental-subjekt i en kløvet sætning, så verbet er 'was'."},
{"l":9112,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ubetydelig' på engelsk?","o":["negligent","negligible","eligible","legible"],"a":"negligible","r":"'Negligible' = så lille, at man kan se bort fra det."},
{"l":9125,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'uden fortilfælde' på engelsk?","o":["unpredictable","unsupervised","unprecedented","unprotected"],"a":"unprecedented","r":"'Unprecedented' betyder, at det aldrig er sket før."},
{"l":9136,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'udbredt' på engelsk?","o":["relevant","prudent","prominent","prevalent"],"a":"prevalent","r":"'Prevalent' = udbredt."},
{"l":9147,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'fattig / nødlidende' på engelsk?","o":["destitute","resolute","desolate","obstinate"],"a":"destitute","r":"'Destitute' = uden midler."},
{"l":9149,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'gavnlig' på engelsk?","o":["superficial","beneficial","artificial","official"],"a":"beneficial","r":"'Beneficial' betyder gavnlig."},
{"l":9159,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'indbringende' på engelsk?","o":["decorative","ludicrous","lucrative","creative"],"a":"lucrative","r":"'Lucrative' = indbringende."},
{"l":9162,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'nært forestående' på engelsk?","o":["eminent","immense","innocent","imminent"],"a":"imminent","r":"'Imminent' betyder, at noget snart sker. 'Eminent' betyder fremtrædende."},
{"l":9174,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'fremtrædende / anset' på engelsk?","o":["eminent","imminent","emergent","elegant"],"a":"eminent","r":"'Eminent' betyder fremtrædende."},
{"l":9182,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'hypotese' på engelsk?","o":["hypnosis","hypothesis","synthesis","emphasis"],"a":"hypothesis","r":"'Hypothesis' = hypotese, antagelse."},
{"l":9190,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'impeccable' i 'Her manners at the dinner were impeccable.'?","o":["upassende","gammeldags","upåklagelige","uforståelige"],"a":"upåklagelige","r":"'Impeccable' betyder fejlfri eller upåklagelig."},
{"l":9200,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Not ___ what to say, she simply smiled and nodded.'","o":["known","to know","knew","knowing"],"a":"knowing","r":"'Not knowing what to say' er en nægtende participiumsætning, der forklarer årsagen til, at hun smilede."},
{"l":9205,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'tvetydighed' på engelsk?","o":["ambiguity","ambition","antiquity","ubiquity"],"a":"ambiguity","r":"'Ambiguity' = tvetydighed."},
{"l":9217,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'nytteløs' på engelsk?","o":["fertile","futile","fragile","hostile"],"a":"futile","r":"'Futile' = nytteløs."},
{"l":9228,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'iboende' på engelsk?","o":["coherent","indolent","inherent","insolent"],"a":"inherent","r":"'Inherent' = iboende."},
{"l":9235,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'indrømme / give efter' på engelsk?","o":["conceive","conceal","convene","concede"],"a":"concede","r":"'Concede' betyder at indrømme eller opgive."},
{"l":9247,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'støtte / anbefale' på engelsk?","o":["endorse","endure","enforce","enclose"],"a":"endorse","r":"'Endorse' betyder at støtte offentligt."},
{"l":9252,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'forlige / forene' på engelsk?","o":["recollect","reconcile","recline","recount"],"a":"reconcile","r":"'Reconcile' = forlige, få til at passe sammen."},
{"l":9260,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Some scientists believe the number of hedgehogs in Britain has fallen sharply, while others argue that the animals have simply moved into gardens where they are harder to count.' Hvad er forskerne uenige om?","o":["Hvor pindsvinene kommer fra","Hvad pindsvin spiser i haverne","Om der reelt er færre pindsvin","Hvordan man fanger pindsvin"],"a":"Om der reelt er færre pindsvin","r":"Nogle mener, at antallet er faldet, andre at dyrene bare er sværere at tælle. Uenigheden handler om, hvorvidt der faktisk er færre."},
{"l":9275,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'incitament / tilskyndelse' på engelsk?","o":["initiative","invective","incidence","incentive"],"a":"incentive","r":"'Incentive' = noget, der motiverer."},
{"l":9287,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'afskrækkende middel' på engelsk?","o":["deterrent","detergent","detriment","deposit"],"a":"deterrent","r":"'Deterrent' = noget, der afskrækker. Rengøringsmiddel hedder 'detergent'."},
{"l":9296,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'lette / gøre muligt' på engelsk?","o":["fabricate","facilitate","fluctuate","formulate"],"a":"facilitate","r":"'Facilitate' betyder at gøre noget lettere."},
{"l":9300,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'tøven' på engelsk i 'After a moment of ___, she agreed to give the speech.'?","o":["hostility","humiliation","hesitation","hospitality"],"a":"hesitation","r":"'Hesitation' betyder tøven. 'Hostility' er fjendtlighed, og 'hospitality' er gæstfrihed."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'bekræfte / efterprøve' på engelsk?","o":["vilify","notify","testify","verify"],"a":"verify","r":"'Verify' = kontrollere, at noget er sandt."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'It is essential that every pupil ___ a copy of the safety rules.'","o":["receive","receiving","received","to receive"],"a":"receive","r":"Efter 'It is essential that' kan man bruge konjunktiv, dvs. grundformen 'receive' uden endelse."},
{"l":9321,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'trives / blomstre' på engelsk?","o":["strive","thrive","shrink","drift"],"a":"thrive","r":"'Thrive' = trives."},
{"l":9333,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'efterligne' på engelsk?","o":["emanate","elevate","emulate","enumerate"],"a":"emulate","r":"'Emulate' = efterligne."},
{"l":9340,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'sceptical' i 'a sceptical audience'?","o":["bored","large","noisy","convinced"],"a":"convinced","r":"'Sceptical' betyder skeptisk og i tvivl, så det modsatte er 'convinced' (overbevist)."},
{"l":9345,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'underbygge / dokumentere' på engelsk?","o":["substantiate","substitute","subsidise","subordinate"],"a":"substantiate","r":"'Substantiate' = bevise, underbygge."},
{"l":9357,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'modvillig / afvisende over for' på engelsk i 'He is not ___ to risk'?","o":["adverse","averse","diverse","immune"],"a":"averse","r":"'Averse to' betyder imod eller afvisende over for."},
{"l":9370,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'red tape' i 'Starting a new club involved a lot of red tape.'?","o":["festlige bånd","hård konkurrence","bureaukrati","dyre udgifter"],"a":"bureaukrati","r":"'Red tape' betyder bureaukrati og unødvendigt papirarbejde."},
{"l":9380,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'udskyde / trække tiden' på engelsk?","o":["proliferate","prosecute","propagate","procrastinate"],"a":"procrastinate","r":"'Procrastinate' = udsætte ting."},
{"l":9400,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'loathes' i 'My brother loathes getting up early on Saturdays.'?","o":["afskyr","elsker","glemmer","undgår"],"a":"afskyr","r":"'Loathe' betyder at afsky. Det er stærkere end 'dislike'."},
{"l":9403,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'smuthul' på engelsk?","o":["porthole","loophole","foothold","pothole"],"a":"loophole","r":"'Loophole' = smuthul (i en lov)."},
{"l":9426,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'fremsynethed' på engelsk?","o":["hindsight","oversight","foresight","eyesight"],"a":"foresight","r":"'Foresight' = evnen til at forudse."},
{"l":9460,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The weather forecast promised a perfect beach day. We spent the afternoon in a café watching the rain hammer against the windows.' Hvad viser teksten?","o":["At de hellere ville sidde på café","At de havde glemt badetøjet","At stranden var lukket den dag","At vejrudsigten tog helt fejl"],"a":"At vejrudsigten tog helt fejl","r":"Der var lovet perfekt strandvejr, men det regnede kraftigt. Kontrasten viser ironisk, at udsigten tog fejl."},
{"l":9480,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'prolific' i 'a prolific writer'?","o":["unproductive","famous","talented","careful"],"a":"unproductive","r":"'Prolific' betyder produktiv, altså en der skriver meget, så det modsatte er 'unproductive'."},
{"l":9530,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'at a stretch' i 'She can read for five hours at a stretch.'?","o":["med besvær","i træk","højst","om aftenen"],"a":"i træk","r":"'At a stretch' betyder i træk eller uden pause."},
{"l":9560,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'a wake-up call' i 'Failing the mock exam was a wake-up call for Jonas.'?","o":["en glad overraskelse","et opkald om morgenen","et tydeligt varsko","en ufortjent straf"],"a":"et tydeligt varsko","r":"'A wake-up call' er en hændelse, der får én til at indse, at man må ændre noget."},
{"l":9580,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'bent over backwards' i 'The hotel staff bent over backwards to help us.'?","o":["lavede gymnastik","var meget uhøflige","opgav med det samme","gjorde alt for at"],"a":"gjorde alt for at","r":"'Bend over backwards' betyder at gøre alt, hvad man kan, for at hjælpe nogen."},
{"l":9600,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'at opfinde den dybe tallerken' på engelsk?","o":["to reinvent the wheel","to take the wheel","to break the mould","to grease the wheels"],"a":"to reinvent the wheel","r":"'to reinvent the wheel' betyder at opfinde den dybe tallerken. Udtrykket betyder at bruge tid på noget, der allerede findes."},
{"l":9620,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'feigned' i 'He feigned illness to avoid the maths test.'?","o":["overvandt","foregav","fik","frygtede"],"a":"foregav","r":"'Feign' betyder at foregive eller simulere; han lod som om, han var syg."},
{"l":9640,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'If she weren't so shy, she ___ for the class council last week.'","o":["would run","will run","would have run","had run"],"a":"would have run","r":"Blandet betingelse: en vedvarende egenskab ('weren't so shy') påvirker fortiden ('last week'), så man bruger 'would have run'."},
{"l":9670,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The hotel advertised itself as cosy. On arrival, we discovered that this meant our room was roughly the size of a wardrobe.' Hvad mener skribenten?","o":["At værelset var meget hyggeligt","At hotellet havde store skabe","At værelset var nyistandsat","At værelset var ekstremt lille"],"a":"At værelset var ekstremt lille","r":"Skribenten afslører ironisk, at 'cosy' i reklamen dækkede over, at værelset var lille som et klædeskab."},
{"l":9700,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The coach insisted that every player ___ on time for training.'","o":["be","being","to be","been"],"a":"be","r":"Efter 'insist that' kan man bruge konjunktiv: grundformen 'be' uden endelse. 'To be' og 'being' kan ikke stå efter 'that'."},
{"l":9720,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man afslutter et formelt brev, der begyndte uden modtagerens navn?","o":["Lots of love","Yours faithfully","Take care","See you around"],"a":"Yours faithfully","r":"I britisk engelsk afslutter man et formelt brev til en ukendt modtager med 'Yours faithfully'. De andre er uformelle."},
{"l":9740,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The instructions claimed the shelf could be assembled in ten minutes. Three hours, two broken screws and one very long phone call later, it was finally standing.' Hvad antyder skribenten?","o":["At reolen var hurtig og nem at samle","At skribenten havde mistet vejledningen","At vejledningen var alt for optimistisk","At telefonen gik i stykker undervejs"],"a":"At vejledningen var alt for optimistisk","r":"'Claimed' og kontrasten mellem ti minutter og tre timer viser, at vejledningens løfte var urealistisk."},
{"l":9770,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The two classes have a ___ rivalry that goes back many years.'","o":["outstanding","freestanding","notwithstanding","long-standing"],"a":"long-standing","r":"'Long-standing' betyder langvarig, som har eksisteret længe. 'Outstanding' betyder fremragende eller udestående."},
{"l":9790,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The report, ___ in 2019, still influences how schools teach climate science.'","o":["first published","first publishing","having published","was first published"],"a":"first published","r":"'First published in 2019' er en forkortet passiv participiumsætning (= which was first published). 'Was first published' ville kræve et relativt pronomen."},
{"l":9820,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'stifle' i 'She tried to stifle a yawn during the long presentation.'?","o":["efterligne","undertrykke","fremkalde","nyde"],"a":"undertrykke","r":"'Stifle' betyder at undertrykke eller kvæle, fx et gab eller et grin."},
{"l":9850,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: '___ from the top of the tower, the town looks like a model village.'","o":["Seeing","Saw","Seen","Having seen"],"a":"Seen","r":"Byen bliver set fra tårnet, så det er en passiv participiumsætning: 'Seen from the top'. 'Seeing' ville betyde, at byen selv ser."},
{"l":9880,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'hit the ground running' i 'The new coach hit the ground running and won her first three matches.'?","o":["faldt og slog sig","startede langsomt","løb fra ansvaret","kom hurtigt godt i gang"],"a":"kom hurtigt godt i gang","r":"'Hit the ground running' betyder at gå i gang med fuld kraft og have succes fra starten."},
{"l":9890,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Hardly had the guests arrived ___ the power went out.'","o":["when","than","then","while"],"a":"when","r":"Det faste mønster er 'Hardly had ... when ...'. 'Than' hører til 'No sooner'."},
{"l":9940,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Were the council ___ the plan, the park would be lost.'","o":["approving","to approve","approved","approve"],"a":"to approve","r":"'Were + subjekt + to + grundform' er en formel, inverteret type 2-betingelse (= If the council approved)."},
{"l":9961,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'et utal' på engelsk i 'a ___ of options'?","o":["mirage","shortage","myriad","review"],"a":"myriad","r":"'Myriad' = utallige."},
{"l":9990,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'ascend' i 'ascend the stairs'?","o":["decorate","measure","block","descend"],"a":"descend","r":"'Ascend' betyder at stige op, så det modsatte er 'descend' (gå ned)."},
{"l":10000,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'omvendt' på engelsk?","o":["conversely","concisely","consequently","conveniently"],"a":"conversely","r":"'Conversely' = omvendt."},
{"l":10000,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'være indbegrebet af' på engelsk?","o":["optimise","epitomise","economise","apologise"],"a":"epitomise","r":"'Epitomise' = være et typisk eksempel på."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
